<?php
/**
 * Media Manager - registry and admin page for media generated by Draxira
 *
 * Every attachment that any Draxira generator creates is recorded in a single
 * registry stored with the WordPress Options API (no custom tables). The Media
 * Manager page lists the registry and can remove ONLY the attachments that are
 * recorded in it.
 *
 * @package Draxira
 * @subpackage Includes
 * @since 1.0.7
 */

// Prevent direct access
if (!defined('ABSPATH')) {
    exit;
}

/**
 * Class Draxira_Media
 *
 * @since 1.0.7
 */
class Draxira_Media
{
    /**
     * Option name that holds the registry.
     */
    const OPTION = 'draxira_media_registry';

    /**
     * Rows shown per page in the Media Manager table.
     */
    const PER_PAGE = 25;

    /**
     * @var Draxira_Media|null
     */
    private static $instance = null;

    /**
     * True while a bulk operation runs, so the delete_attachment hook does not
     * rewrite the registry underneath it.
     *
     * @var bool
     */
    private static $bulk = false;

    /**
     * @return Draxira_Media
     */
    public static function get_instance()
    {
        if (null === self::$instance) {
            self::$instance = new self();
        }
        return self::$instance;
    }

    /**
     * Constructor.
     */
    private function __construct()
    {
        add_action('admin_menu', [$this, 'add_menu'], 12);
        add_action('admin_init', [$this, 'handle_actions']);
        // Keep the registry accurate if an attachment is deleted from the normal Media Library.
        add_action('delete_attachment', [__CLASS__, 'on_delete_attachment'], 10, 1);
    }

    /* ------------------------------------------------------------------
     * Registry API (static so every generator can call it)
     * ---------------------------------------------------------------- */

    /**
     * Get the whole registry.
     *
     * @return array attachment_id => record
     */
    public static function get_registry()
    {
        $registry = get_option(self::OPTION, []);
        return is_array($registry) ? $registry : [];
    }

    /**
     * Persist the registry (never autoloaded: it can grow large).
     *
     * @param array $registry Registry.
     * @return void
     */
    private static function save_registry(array $registry)
    {
        update_option(self::OPTION, $registry, false);
    }

    /**
     * Record an attachment as generated by Draxira.
     *
     * @param int    $attachment_id Attachment ID.
     * @param int    $content_id    Post/product/variation the media belongs to.
     * @param string $post_type     Post type of that content (looked up when empty).
     * @param string $source        Generator name, e.g. posts, products.
     * @return bool True when recorded.
     */
    public static function register($attachment_id, $content_id = 0, $post_type = '', $source = '')
    {
        $attachment_id = absint($attachment_id);
        if (!$attachment_id || 'attachment' !== get_post_type($attachment_id)) {
            return false;
        }

        // Flag on the attachment itself: a second, independent marker used as a safety check on cleanup.
        update_post_meta($attachment_id, DRAXIRA_META_KEY, '1');

        $content_id = absint($content_id);
        $post_type = sanitize_key($post_type);
        if ('' === $post_type && $content_id) {
            $post_type = (string) get_post_type($content_id);
        }

        $file = get_attached_file($attachment_id);
        $registry = self::get_registry();

        $registry[$attachment_id] = [
            'attachment_id' => $attachment_id,
            'file' => $file ? _wp_relative_upload_path($file) : '',
            'filename' => $file ? wp_basename($file) : '',
            'content_id' => $content_id,
            'post_type' => $post_type,
            'source' => sanitize_key($source),
            'generated_at' => isset($registry[$attachment_id]['generated_at']) ? (int) $registry[$attachment_id]['generated_at'] : time(),
        ];

        self::save_registry($registry);
        return true;
    }

    /**
     * Remove one attachment from the registry.
     *
     * @param int $attachment_id Attachment ID.
     * @return void
     */
    public static function unregister($attachment_id)
    {
        $attachment_id = absint($attachment_id);
        $registry = self::get_registry();
        if (isset($registry[$attachment_id])) {
            unset($registry[$attachment_id]);
            self::save_registry($registry);
        }
    }

    /**
     * delete_attachment hook callback.
     *
     * @param int $post_id Attachment ID.
     * @return void
     */
    public static function on_delete_attachment($post_id)
    {
        if (self::$bulk) {
            return;
        }
        self::unregister($post_id);
    }

    /**
     * Delete every attachment recorded in the registry - and nothing else.
     *
     * An attachment is only deleted when it is in the registry AND still carries
     * Draxira's own flag. wp_delete_attachment() removes the DB record, the
     * original file, all generated thumbnails and the attachment metadata.
     *
     * @return array Counts: deleted, missing, skipped, failed.
     */
    public static function clear_all()
    {
        $stats = ['deleted' => 0, 'missing' => 0, 'skipped' => 0, 'failed' => 0];
        $registry = self::get_registry();

        self::$bulk = true;
        foreach (array_keys($registry) as $attachment_id) {
            $attachment_id = absint($attachment_id);
            $attachment = $attachment_id ? get_post($attachment_id) : null;

            if (!$attachment || 'attachment' !== $attachment->post_type) {
                $stats['missing']++;
                unset($registry[$attachment_id]);
                continue;
            }

            if ('1' !== (string) get_post_meta($attachment_id, DRAXIRA_META_KEY, true)) {
                // Registered but not flagged: refuse to touch it, just drop the stale record.
                $stats['skipped']++;
                unset($registry[$attachment_id]);
                continue;
            }

            if (wp_delete_attachment($attachment_id, true)) {
                $stats['deleted']++;
                unset($registry[$attachment_id]);
            } else {
                $stats['failed']++;
            }
        }
        self::$bulk = false;

        self::save_registry($registry);
        return $stats;
    }

    /**
     * Remove registry records whose attachment no longer exists.
     *
     * @return int Number of records removed.
     */
    public static function prune_stale()
    {
        $registry = self::get_registry();
        $existing = self::get_existing_ids(array_keys($registry));
        $removed = 0;

        foreach (array_keys($registry) as $attachment_id) {
            if (!isset($existing[absint($attachment_id)])) {
                unset($registry[$attachment_id]);
                $removed++;
            }
        }

        if ($removed) {
            self::save_registry($registry);
        }
        return $removed;
    }

    /**
     * Which of the given attachment IDs still exist? One query instead of one per record.
     *
     * @param array $ids Attachment IDs.
     * @return array id => true
     */
    private static function get_existing_ids(array $ids)
    {
        $ids = array_filter(array_map('absint', $ids));
        if (empty($ids)) {
            return [];
        }

        $found = get_posts([
            'post_type' => 'attachment',
            'post_status' => 'any',
            'post__in' => $ids,
            'posts_per_page' => -1,
            'fields' => 'ids',
            'orderby' => 'none',
            'no_found_rows' => true,
        ]);

        return array_fill_keys(array_map('absint', $found), true);
    }

    /**
     * Find attachments created by earlier Draxira versions that are not tracked yet.
     *
     * Only the plugin's own filler image titles (dummy_content_filler_img_N and
     * dummy_content_filler_product_img_N) are matched, exactly.
     *
     * @return array Attachment IDs.
     */
    public static function find_untracked_legacy()
    {
        $registry = self::get_registry();
        $candidates = get_posts([
            'post_type' => 'attachment',
            'post_status' => 'inherit',
            's' => 'dummy_content_filler_',
            'posts_per_page' => -1,
            'fields' => 'ids',
            'no_found_rows' => true,
        ]);

        $ids = [];
        foreach ($candidates as $attachment_id) {
            if (isset($registry[$attachment_id])) {
                continue;
            }
            $title = (string) get_post_field('post_title', $attachment_id);
            if (preg_match('/^dummy_content_filler_(?:product_)?img_\d+$/', $title)) {
                $ids[] = (int) $attachment_id;
            }
        }
        return $ids;
    }

    /**
     * Add legacy attachments to the registry.
     *
     * @return int Number imported.
     */
    public static function import_legacy()
    {
        $imported = 0;
        foreach (self::find_untracked_legacy() as $attachment_id) {
            $owner = get_posts([
                'post_type' => 'any',
                'post_status' => 'any',
                'meta_key' => '_thumbnail_id',
                'meta_value' => $attachment_id,
                'posts_per_page' => 1,
                'fields' => 'ids',
                'no_found_rows' => true,
            ]);
            $content_id = !empty($owner) ? (int) $owner[0] : 0;
            $title = (string) get_post_field('post_title', $attachment_id);
            $source = (false !== strpos($title, '_product_')) ? 'products' : 'posts';

            if (self::register($attachment_id, $content_id, '', $source)) {
                $imported++;
            }
        }
        return $imported;
    }

    /* ------------------------------------------------------------------
     * Admin
     * ---------------------------------------------------------------- */

    /**
     * Register the submenu.
     *
     * @return void
     */
    public function add_menu()
    {
        add_submenu_page(
            'draxira',
            'Media Manager',
            'Media Manager',
            'manage_options',
            'draxira-media',
            [$this, 'render_page']
        );
    }

    /**
     * Handle the three POST actions (clear / prune / import).
     *
     * @return void
     */
    public function handle_actions()
    {
        if (!isset($_POST['draxira_media_action'])) {
            return;
        }
        if (!current_user_can('manage_options')) {
            return;
        }

        $action = sanitize_key(wp_unslash($_POST['draxira_media_action']));
        if (!in_array($action, ['clear', 'prune', 'import'], true)) {
            return;
        }

        $nonce = isset($_POST['_wpnonce']) ? sanitize_text_field(wp_unslash($_POST['_wpnonce'])) : '';
        if (!wp_verify_nonce($nonce, 'draxira_media_' . $action)) {
            set_transient('draxira_media_results', [
                'message' => __('Security check failed. Please try again.', 'draxira'),
                'type' => 'error',
            ], 45);
            wp_safe_redirect(admin_url('admin.php?page=draxira-media'));
            exit;
        }

        if ('clear' === $action) {
            $stats = self::clear_all();
            $message = sprintf(
                /* translators: 1: deleted count, 2: stale record count, 3: skipped count */
                __('Deleted %1$d Draxira media files. Removed %2$d stale records. Skipped %3$d unflagged records.', 'draxira'),
                $stats['deleted'],
                $stats['missing'],
                $stats['skipped']
            );
            $type = $stats['failed'] ? 'error' : 'success';
            if ($stats['failed']) {
                /* translators: %d: number of attachments that could not be deleted */
                $message .= ' ' . sprintf(__('%d could not be deleted and are still listed.', 'draxira'), $stats['failed']);
            }
        } elseif ('prune' === $action) {
            $removed = self::prune_stale();
            /* translators: %d: number of removed records */
            $message = sprintf(__('Removed %d stale records.', 'draxira'), $removed);
            $type = 'success';
        } else {
            $imported = self::import_legacy();
            /* translators: %d: number of imported attachments */
            $message = sprintf(__('Added %d existing Draxira filler images to the registry.', 'draxira'), $imported);
            $type = 'success';
        }

        set_transient('draxira_media_results', ['message' => $message, 'type' => $type], 45);
        wp_safe_redirect(admin_url('admin.php?page=draxira-media'));
        exit;
    }

    /**
     * Human label for a source slug.
     *
     * @param string $source Source slug.
     * @return string
     */
    private function source_label($source)
    {
        $labels = [
            'posts' => __('Posts / Post Types', 'draxira'),
            'products' => __('Products', 'draxira'),
        ];
        return isset($labels[$source]) ? $labels[$source] : ('' !== $source ? ucfirst($source) : '—');
    }

    /**
     * Render the Media Manager page.
     *
     * @return void
     */
    public function render_page()
    {
        if (!current_user_can('manage_options')) {
            return;
        }

        $registry = self::get_registry();
        uasort($registry, function ($a, $b) {
            return (int) $b['generated_at'] - (int) $a['generated_at'];
        });

        $total = count($registry);
        $existing = self::get_existing_ids(array_keys($registry));
        $exists_count = count($existing);
        $missing_count = $total - $exists_count;
        $untracked = self::find_untracked_legacy();

        $paged = isset($_GET['paged']) ? max(1, absint(wp_unslash($_GET['paged']))) : 1; // phpcs:ignore WordPress.Security.NonceVerification.Recommended
        $pages = max(1, (int) ceil($total / self::PER_PAGE));
        $paged = min($paged, $pages);
        $rows = array_slice($registry, ($paged - 1) * self::PER_PAGE, self::PER_PAGE, true);

        $date_format = get_option('date_format') . ' ' . get_option('time_format');
        ?>
        <div class="wrap draxira">
            <h1><?php esc_html_e('Draxira – Dummy Content Generator - Media Manager', 'draxira'); ?></h1>
            <?php Draxira_Helpers::render_nav('draxira-media'); ?>

            <?php
            $results = get_transient('draxira_media_results');
            if ($results) {
                delete_transient('draxira_media_results');
                $notice_class = (isset($results['type']) && 'error' === $results['type']) ? 'notice-error' : 'notice-success';
                echo '<div class="notice ' . esc_attr($notice_class) . '"><p>' . esc_html($results['message']) . '</p></div>';
            }
            ?>

            <div class="dx-stats">
                <div class="dx-stat">
                    <span class="dx-stat-value"><?php echo esc_html(number_format_i18n($total)); ?></span>
                    <span class="dx-stat-label"><?php esc_html_e('Tracked media records', 'draxira'); ?></span>
                </div>
                <div class="dx-stat is-good">
                    <span class="dx-stat-value"><?php echo esc_html(number_format_i18n($exists_count)); ?></span>
                    <span class="dx-stat-label"><?php esc_html_e('Still in Media Library', 'draxira'); ?></span>
                </div>
                <div class="dx-stat <?php echo $missing_count ? 'is-warn' : ''; ?>">
                    <span class="dx-stat-value"><?php echo esc_html(number_format_i18n($missing_count)); ?></span>
                    <span class="dx-stat-label"><?php esc_html_e('Stale records (attachment gone)', 'draxira'); ?></span>
                </div>
            </div>

            <div class="dx-card">
                <div class="dx-card-head">
                    <h3><?php esc_html_e('Draxira-generated media', 'draxira'); ?></h3>
                    <p class="description"><?php esc_html_e('Only files created by Draxira and recorded here are listed. Your own uploads are never shown or touched.', 'draxira'); ?></p>
                </div>

                <?php if (empty($registry)): ?>
                    <div class="dx-empty">
                        <p><?php esc_html_e('No Draxira media has been tracked yet. Generate posts or products with featured images and they will appear here.', 'draxira'); ?></p>
                    </div>
                <?php else: ?>
                    <table class="widefat striped dx-media-table">
                        <thead>
                            <tr>
                                <th><?php esc_html_e('Thumbnail', 'draxira'); ?></th>
                                <th><?php esc_html_e('Attachment ID', 'draxira'); ?></th>
                                <th><?php esc_html_e('Filename', 'draxira'); ?></th>
                                <th><?php esc_html_e('Associated Content', 'draxira'); ?></th>
                                <th><?php esc_html_e('Post Type', 'draxira'); ?></th>
                                <th><?php esc_html_e('Source', 'draxira'); ?></th>
                                <th><?php esc_html_e('Generated', 'draxira'); ?></th>
                                <th><?php esc_html_e('Status', 'draxira'); ?></th>
                            </tr>
                        </thead>
                        <tbody>
                            <?php foreach ($rows as $attachment_id => $record):
                                $attachment_id = absint($attachment_id);
                                $is_present = isset($existing[$attachment_id]);
                                $file_path = $is_present ? get_attached_file($attachment_id) : '';
                                $file_ok = $file_path && file_exists($file_path);

                                if (!$is_present) {
                                    $status_class = 'is-muted';
                                    $status_label = __('Removed', 'draxira');
                                } elseif (!$file_ok) {
                                    $status_class = 'is-warn';
                                    $status_label = __('File missing', 'draxira');
                                } else {
                                    $status_class = 'is-good';
                                    $status_label = __('Exists', 'draxira');
                                }

                                $content_id = isset($record['content_id']) ? absint($record['content_id']) : 0;
                                $content = $content_id ? get_post($content_id) : null;
                                $type_obj = (!empty($record['post_type'])) ? get_post_type_object($record['post_type']) : null;
                                ?>
                                <tr>
                                    <td class="dx-thumb">
                                        <?php
                                        if ($is_present && $file_ok) {
                                            echo wp_kses_post(wp_get_attachment_image($attachment_id, [48, 48]));
                                        } else {
                                            echo '<span class="dashicons dashicons-format-image" aria-hidden="true"></span>';
                                        }
                                        ?>
                                    </td>
                                    <td>
                                        <?php if ($is_present): ?>
                                            <a href="<?php echo esc_url(get_edit_post_link($attachment_id)); ?>">#<?php echo esc_html($attachment_id); ?></a>
                                        <?php else: ?>
                                            #<?php echo esc_html($attachment_id); ?>
                                        <?php endif; ?>
                                    </td>
                                    <td><code><?php echo esc_html(isset($record['filename']) ? $record['filename'] : ''); ?></code></td>
                                    <td>
                                        <?php if ($content): ?>
                                            <a href="<?php echo esc_url(get_edit_post_link($content_id)); ?>"><?php echo esc_html(get_the_title($content_id)); ?></a>
                                            <small>(ID: <?php echo esc_html($content_id); ?>)</small>
                                        <?php elseif ($content_id): ?>
                                            <em><?php esc_html_e('Deleted content', 'draxira'); ?></em>
                                            <small>(ID: <?php echo esc_html($content_id); ?>)</small>
                                        <?php else: ?>
                                            <em><?php esc_html_e('Not linked', 'draxira'); ?></em>
                                        <?php endif; ?>
                                    </td>
                                    <td><?php echo esc_html($type_obj ? $type_obj->labels->singular_name : (isset($record['post_type']) && $record['post_type'] ? $record['post_type'] : '—')); ?></td>
                                    <td><?php echo esc_html($this->source_label(isset($record['source']) ? $record['source'] : '')); ?></td>
                                    <td><?php echo esc_html(wp_date($date_format, (int) $record['generated_at'])); ?></td>
                                    <td><span class="dx-badge <?php echo esc_attr($status_class); ?>"><?php echo esc_html($status_label); ?></span></td>
                                </tr>
                            <?php endforeach; ?>
                        </tbody>
                    </table>

                    <?php if ($pages > 1): ?>
                        <div class="tablenav dx-pagination">
                            <div class="tablenav-pages">
                                <?php
                                echo wp_kses_post(paginate_links([
                                    'base' => add_query_arg('paged', '%#%', admin_url('admin.php?page=draxira-media')),
                                    'format' => '',
                                    'current' => $paged,
                                    'total' => $pages,
                                    'prev_text' => '&laquo;',
                                    'next_text' => '&raquo;',
                                ]));
                                ?>
                            </div>
                        </div>
                    <?php endif; ?>
                <?php endif; ?>
            </div>

            <?php if (!empty($untracked)): ?>
                <div class="dx-card">
                    <div class="dx-card-head">
                        <h3><?php esc_html_e('Existing Draxira images found', 'draxira'); ?></h3>
                        <p class="description">
                            <?php
                            echo esc_html(sprintf(
                                /* translators: %d: number of untracked attachments */
                                _n(
                                    '%d filler image from an earlier Draxira version is in your Media Library but not tracked yet.',
                                    '%d filler images from an earlier Draxira version are in your Media Library but not tracked yet.',
                                    count($untracked),
                                    'draxira'
                                ),
                                count($untracked)
                            ));
                            ?>
                            <?php esc_html_e('Only images titled dummy_content_filler_img_N / dummy_content_filler_product_img_N are matched.', 'draxira'); ?>
                        </p>
                    </div>
                    <form method="post" action="">
                        <?php wp_nonce_field('draxira_media_import'); ?>
                        <input type="hidden" name="draxira_media_action" value="import">
                        <button type="submit" class="button"><?php esc_html_e('Add these to the Draxira media registry', 'draxira'); ?></button>
                    </form>
                </div>
            <?php endif; ?>

            <div class="dx-card dx-danger-zone">
                <div class="dx-card-head">
                    <h3><?php esc_html_e('Cleanup', 'draxira'); ?></h3>
                </div>
                <div class="dx-actions-row">
                    <form method="post" action="">
                        <?php wp_nonce_field('draxira_media_prune'); ?>
                        <input type="hidden" name="draxira_media_action" value="prune">
                        <button type="submit" class="button" <?php disabled($missing_count, 0); ?>><?php esc_html_e('Remove stale records', 'draxira'); ?></button>
                    </form>

                    <form method="post" action="">
                        <?php wp_nonce_field('draxira_media_clear'); ?>
                        <input type="hidden" name="draxira_media_action" value="clear">
                        <button type="submit" class="button button-link-delete" <?php disabled($total, 0); ?>
                            data-confirm-message="<?php echo esc_attr__("FINAL WARNING!\n\nThis will PERMANENTLY DELETE every media file generated by Draxira (files, thumbnails and attachment records).\nYour own uploads are not touched.\nNo backup. No trash. Really sure?", 'draxira'); ?>">
                            <?php esc_html_e('Clear All Draxira Media', 'draxira'); ?>
                        </button>
                    </form>
                </div>
                <p class="description"><?php esc_html_e('Clear All Draxira Media deletes only attachments recorded in the registry above. Posts and products that used them stay in place without a featured image.', 'draxira'); ?></p>
            </div>
        </div>
        <?php
    }
}
